-- Logical cash holding accounts for month-to-date cash revenue; no new table.
on conflict (account_code) do update set display_name=excluded.display_name,financial_domain=excluded.financial_domain,business_unit=excluded.business_unit,record_status='ACTIVE',account_roles=excluded.account_roles,purpose_note=excluded.purpose_note,source=excluded.source,source_reference=excluded.source_reference,updated_at=now();
